using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class PortalTileApply {
 const string E="Assets/Afrer_Seconds/05.Model/Environment/B5/";static string O=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../../Docs/검수/2026-11-07_C01_PortalTiles/"));
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_B5_Circular.unity"))throw new Exception("Saved B5 edit scene required");var room=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform.Find("C01_Experiment_Art");var material=room.Find("AF_C01_CurvedLining").GetComponentInChildren<Renderer>().sharedMaterials.Single();var logs=new List<string>();Application.LogCallback cb=(m,st,t)=>{if(t==LogType.Warning||t==LogType.Error||t==LogType.Exception)logs.Add(m);};Application.logMessageReceived+=cb;
 try{string p=E+"AF_C01_PortalTileInfill.fbx";AssetDatabase.ImportAsset(p,ImportAssetOptions.ForceSynchronousImport|ImportAssetOptions.ForceUpdate);var mi=(ModelImporter)AssetImporter.GetAtPath(p);mi.isReadable=true;mi.importAnimation=false;mi.importCameras=false;mi.importLights=false;mi.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),"S1_Coat"),material);mi.SaveAndReimport();var previous=room.Find("AF_C01_PortalTileInfill");if(previous)UnityEngine.Object.DestroyImmediate(previous.gameObject);var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(p),room);g.name="AF_C01_PortalTileInfill";g.transform.localPosition=Vector3.zero;g.transform.localRotation=Quaternion.identity;g.transform.localScale=Vector3.one;foreach(var mf in g.GetComponentsInChildren<MeshFilter>()){var c=mf.gameObject.AddComponent<MeshCollider>();c.sharedMesh=mf.sharedMesh;}Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);var result=new{asset=p,guid=AssetDatabase.AssetPathToGUID(p),material=AssetDatabase.GetAssetPath(material),triangles=g.GetComponentsInChildren<MeshFilter>().Sum(m=>m.sharedMesh.triangles.Length/3),logs};File.WriteAllText(O+"apply.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;
 }finally{Application.logMessageReceived-=cb;}}
 public static object Audit(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty)throw new Exception("Saved edit scene required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var room=root.Find("C01_Experiment_Art");var g=room.Find("AF_C01_PortalTileInfill");var meshes=g.GetComponentsInChildren<MeshFilter>();int bad=0;foreach(var mf in meshes){var m=mf.sharedMesh;var v=m.vertices;var tr=m.triangles;for(int i=0;i<tr.Length;i+=3)if(Vector3.Cross(v[tr[i+1]]-v[tr[i]],v[tr[i+2]]-v[tr[i]]).magnitude*.5f<5e-9f)bad++;}var doors=root.Find("Pocket_Doors_Open").Cast<Transform>().Where(d=>Vector3.Distance(d.position,room.position)<12).ToArray();var checks=new List<object>();Physics.SyncTransforms();foreach(var d in doors){var p=d.Find("Clinical_Portal");int blocked=0;for(int i=0;i<=40;i++)foreach(float x in new[]{-.85f,0,.85f}){var at=p.TransformPoint(new Vector3(x,0,-1.6f+i*.08f));if(Physics.OverlapCapsule(at+Vector3.up*.34f,at+Vector3.up*1.5f,.28f,~0,QueryTriggerInteraction.Ignore).Any(c=>c.transform.IsChildOf(g)))blocked++;}checks.Add(new{d.name,samples=123,blockedByNewTiles=blocked});}var result=new{scene=s.path,dirty=s.isDirty,playing=Application.isPlaying,meshCount=meshes.Length,triangles=meshes.Sum(m=>m.sharedMesh.triangles.Length/3),badTriangles=bad,missingMaterials=g.GetComponentsInChildren<Renderer>().Count(r=>r.sharedMaterials.Any(m=>!m||!m.shader)),colliderMatches=meshes.All(m=>m.GetComponent<MeshCollider>()&&m.GetComponent<MeshCollider>().sharedMesh==m.sharedMesh),checks};File.WriteAllText(O+"audit.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
